function resolveTraceId(): string {
  return `TRC-COR-${Date.now().toString(36).toUpperCase()}`;
}

/**
 * Pure ISO 9223 classification from shoreline distance.
 */
export function classifyCorrosionCategory(distanceToSeaKm: number): Iso9223Category {
  for (const band of ISO9223_BANDS) {
    if (distanceToSeaKm <= band.maxKm) return band.category;
  }
  return 'C1';
}

/**
 * Full salinity / corrosion assessment for a site.
 */
export async function assessSaltCorrosion(input: SaltCorrosionInput): Promise<SaltCorrosionOutput> {
  const { latitude, longitude, distanceToSeaKm: providedDistance, resolveDistance = false } = input;

  let distanceKm = providedDistance;
  let source: 'osm_nominatim' | 'user_entry' = 'user_entry';

  if (distanceKm === undefined && resolveDistance) {
    try {
      const address = await ExternalDataGateway.getInstance().climateProvider.reverseGeocodeNominatim(latitude, longitude);
      const coastal = /sea|gulf|ocean|coast|shore|beach|island|khaleej|fars|bushehr/.test(address.toLowerCase());
      distanceKm = coastal ? 0.0 : 50.0;
      source = 'osm_nominatim';
    } catch {
      distanceKm = 50.0;
      source = 'user_entry';
    }
  }

  if (distanceKm === undefined) {
    throw new Error(
      `SaltCorrosionEngine: distanceToSeaKm is required for site (${latitude.toFixed(4)}, ${longitude.toFixed(4)}) — resolve via OSM/Copernicus Marine shoreline distance or supply explicitly.`
    );
  }

  const category = classifyCorrosionCategory(distanceKm);
  const meta = CATEGORY_META[category];

  return {
    siteName: `Site (${latitude.toFixed(4)}°, ${longitude.toFixed(4)}°)`,
    latitude,
    longitude,
    distanceToSeaKm: distanceKm,
    iso9223Category: category,
    categoryLabel: meta.label,
    categoryLabelFa: meta.labelFa,
    corrosionRisk: meta.risk,
    corrosionRiskFa: meta.riskFa,
    moduleDeratePct: meta.module,
    inverterDeratePct: meta.inverter,
    structureDeratePct: meta.structure,
    maintenanceOpexAdderPct: meta.maintenance,
    durabilityNote: meta.note,
    durabilityNoteFa: meta.noteFa,
    traceId: resolveTraceId(),
    source,
  };
}

// Advanced PV Array Engineering, String Sizing & Deratings (IEC 62548 / NEC 690.7)

import { calculateThermalDerate } from './core/thermalDerate';

export interface ModuleSpecs {
  modelName: string;
  manufacturer: string;
  pmpWatts: number;
  vocVolts: number;
  vmpVolts: number;
  iscAmps: number;
  impAmps: number;
  tempCoeffVocPct: number;  // e.g. -0.28 %/°C
  tempCoeffPmpPct: number;  // e.g. -0.32 %/°C
  noctC: number;            // e.g. 45 °C
  lengthM: number;          // e.g. 2.278 m
  widthM: number;           // e.g. 1.134 m
  bifacialityFactor?: number; // e.g. 0.70
}

export interface InverterSpecs {
  modelName: string;
  manufacturer: string;
  pnomAcKw: number;
  vdcMaxVolts: number;
  vmpptMinVolts: number;
  vmpptMaxVolts: number;
  iscMaxAmpsPerMppt: number;
  imppMaxAmpsPerMppt: number;
  mpptChannelsCount: number;
  efficiencyMaxPct: number;
  isThreePhase: boolean;
}

export interface SiteDeratings {
  ambientTempMinC: number;
  ambientTempMaxC: number;
  soilingLossPct: number;       // e.g. 4.0%
  dcCableLossPct: number;       // e.g. 1.5%
  mismatchAndLidLossPct: number;// e.g. 2.0%
  inverterClippingLossPct: number; // e.g. 1.0%
  systemAvailabilityPct: number;// e.g. 99.0%
  groundAlbedo: number;         // e.g. 0.20
  arrayTiltDeg: number;         // e.g. 30°
}

export interface PvArrayDesignResult {
  totalPvCapacityKwp: number;
  totalModulesCount: number;
  modulesPerString: number;
  parallelStringsCount: number;
  minModulesPerStringAllowed: number;
  maxModulesPerStringAllowed: number;
  stringVocMaxColdVolts: number;
  stringVmpMinHotVolts: number;
  dcAcRatio: number;
  effectiveDeratingFactor: number;
  cellTempHotC: number;
  powerTempDeratePct: number;
  netArrayAreaM2: number;
  interRowSpacingM: number;
  grossRequiredLandAreaM2: number;
  winterSunAltitudeDeg: number;
  warnings: string[];
}

export function designPvArray(
  requiredDailyKwh: number,
  peakSunHours: number,
  module: ModuleSpecs,
  inverter: InverterSpecs,
  deratings: SiteDeratings,
  latitudeDeg: number
): PvArrayDesignResult {
  const warnings: string[] = [];

  // 1. Cell temperature in hot design conditions — unified thermal model (PR-2a-7-P0)
  // G_poa ≈ 1000 W/m² at peak noon; single source of truth: thermalDerate.ts
  const thermal = calculateThermalDerate({
    module: { noctC: module.noctC, tempCoeffPmpPct: module.tempCoeffPmpPct },
    ambientTempMaxC: deratings.ambientTempMaxC,
  });
  const cellTempHotC = thermal.cellTempHotC;

  // 2. Power loss due to temperature
  const powerTempDeratePct = thermal.deratePct;

  // 3. Overall combined system derating factor
  const derateTemp = 1.0 - (powerTempDeratePct / 100.0);
  const derateSoiling = 1.0 - (deratings.soilingLossPct / 100.0);
  const derateCable = 1.0 - (deratings.dcCableLossPct / 100.0);
  const derateMismatch = 1.0 - (deratings.mismatchAndLidLossPct / 100.0);
  const derateInverter = inverter.efficiencyMaxPct / 100.0;
  const derateAvailability = deratings.systemAvailabilityPct / 100.0;

  const effectiveDeratingFactor =
    derateTemp * derateSoiling * derateCable * derateMismatch * derateInverter * derateAvailability;

  // 4. Required DC Array power
  // Energy = P_dc * PSH * Deratings
  const psh = Math.max(2.5, peakSunHours);
  const requiredArrayKwp = requiredDailyKwh / (psh * effectiveDeratingFactor);

  // 5. String Sizing per IEC 62548 / NEC 690.7
  // Cold condition Voc_max:
  const vocTempCoeffDec = module.tempCoeffVocPct / 100.0; // negative number
  const singleModuleVocMaxCold = module.vocVolts * (1.0 + vocTempCoeffDec * (deratings.ambientTempMinC - 25.0));

  // Hot condition Vmp_min:
  // IEC 62548 §7.2: the Vmp temperature coefficient shall be the Pmp coefficient
  // (tempCoeffPmpPct), evaluated at the CELL temperature (cellTempHotC, computed
  // above via the unified NOCT model) — not at ambient temperature.
  // Do NOT "fix" this back to vocTempCoeffDec / ambient-based temperature.
  const vmpTempCoeffDec = module.tempCoeffPmpPct / 100.0;
  const singleModuleVmpMinHot = module.vmpVolts * (1.0 + vmpTempCoeffDec * (cellTempHotC - 25.0));

  // Max series modules limited by Inverter Max Vdc
  const maxModulesAllowed = Math.floor(inverter.vdcMaxVolts / singleModuleVocMaxCold);
  // Max series modules limited by MPPT Max
  // IEC 62548 §7.2: MPPT upper-bound from coldest-day Vmp (Pmp coefficient).
  const singleModuleVmpMaxCold =
    module.vmpVolts * (1.0 + (module.tempCoeffPmpPct / 100.0) * (deratings.ambientTempMinC - 25.0));
  const maxModulesMppt = Math.floor(inverter.vmpptMaxVolts / singleModuleVmpMaxCold);
  const upperLimit = Math.min(maxModulesAllowed, maxModulesMppt);

  // Min series modules limited by MPPT Min
  const minModulesAllowed = Math.ceil(inverter.vmpptMinVolts / singleModuleVmpMinHot);

  if (minModulesAllowed > upperLimit) {
    warnings.push("محدوده ولتاژ MPPT اینورتر برای دمای محیط انتخاب‌شده سازگار نیست (حداقل ماژول از حداکثر بیشتر است).");
  }

  // Choose optimal modules per string (aiming for middle of MPPT window, approx ~70% of VdcMax)
  let chosenModulesPerString = Math.round((minModulesAllowed + upperLimit) / 2);
  chosenModulesPerString = Math.max(1, Math.min(upperLimit, Math.max(minModulesAllowed, chosenModulesPerString)));

  // 6. Calculate total modules and parallel strings
  const singleModuleKwp = module.pmpWatts / 1000.0;
  const initialTotalModules = Math.ceil(requiredArrayKwp / singleModuleKwp);

  let parallelStrings = Math.ceil(initialTotalModules / chosenModulesPerString);
  if (parallelStrings < 1) parallelStrings = 1;

  const totalModulesCount = parallelStrings * chosenModulesPerString;
  const totalPvCapacityKwp = totalModulesCount * singleModuleKwp;

  const stringVocMaxColdVolts = chosenModulesPerString * singleModuleVocMaxCold;
  const stringVmpMinHotVolts = chosenModulesPerString * singleModuleVmpMinHot;

  if (stringVocMaxColdVolts > inverter.vdcMaxVolts) {
    warnings.push(`ولتاژ مدار باز در سردترین روز (${stringVocMaxColdVolts.toFixed(1)}V) از ولتاژ نامی اینورتر (${inverter.vdcMaxVolts}V) بیشتر است! خطر آسیب به اینورتر.`);
  }

  const dcAcRatio = totalPvCapacityKwp / inverter.pnomAcKw;
  if (dcAcRatio > 1.4) {
    warnings.push(`نسبت DC به AC برابر ${dcAcRatio.toFixed(2)} است که بالاتر از سقف بهینه (۱.۳۵) بوده و ممکن است باعث تلفات برش توان (Clipping Loss) شود.`);
  }

  // 7. Area & Inter-row shading distance
  const moduleAreaM2 = module.lengthM * module.widthM;
  const netArrayAreaM2 = totalModulesCount * moduleAreaM2;

  // Inter-row pitch calculation for winter solstice noon:
  // Solar altitude angle at winter solstice: alpha = 90 - latitude - 23.45
  // Row spacing D = H * (cos(tilt) + sin(tilt) / tan(alpha))
  const tiltRad = (deratings.arrayTiltDeg * Math.PI) / 180.0;
  const panelHeightProjectedM = module.lengthM * Math.sin(tiltRad);
  const panelGroundDepthM = module.lengthM * Math.cos(tiltRad);

  // Winter-solstice noon solar altitude from site latitude (PR-2a-7-P0):
  // alpha = 90° - |latitude| - |declination(-23.45°)|, floored at 5° to avoid
  // infinite row spacing at extreme latitudes.
  const winterSolsticeDeclinationDeg = -23.45;
  const solarAltitudeWinterDeg =
    90.0 - Math.abs(latitudeDeg) - Math.abs(winterSolsticeDeclinationDeg);
  const winterSunAltitudeDeg = Math.max(5.0, solarAltitudeWinterDeg);
  const sunElevationRad = (winterSunAltitudeDeg * Math.PI) / 180.0;
  const shadowLengthM = panelHeightProjectedM / Math.tan(sunElevationRad);
  const interRowSpacingM = panelGroundDepthM + shadowLengthM;

  // Gross area incorporates maintenance walkways (+30%)
  const grossRequiredLandAreaM2 = (totalModulesCount / chosenModulesPerString) * (module.widthM * chosenModulesPerString) * interRowSpacingM * 1.30;

  return {
    totalPvCapacityKwp,
    totalModulesCount,
    modulesPerString: chosenModulesPerString,
    parallelStringsCount: parallelStrings,
    minModulesPerStringAllowed: minModulesAllowed,
    maxModulesPerStringAllowed: upperLimit,
    stringVocMaxColdVolts,
    stringVmpMinHotVolts,
    dcAcRatio,
    effectiveDeratingFactor,
    cellTempHotC,
    powerTempDeratePct,
    netArrayAreaM2,
    interRowSpacingM,
    grossRequiredLandAreaM2,
    winterSunAltitudeDeg,
    warnings,
  };
}

// Single source of truth for PV thermal derating (PR-2a-7-P0).
// NOCT-based cell temperature model per IEC 61215 / IEC 62548.
// ALL consumers (App display, pvEngineAdvanced, waterfallLossEngine) MUST
// call calculateThermalDerate() so every tab shows the same number.

export interface ThermalDerateInput {
  module: { noctC: number; tempCoeffPmpPct: number };
  ambientTempMaxC: number;
  irradianceWm2?: number; // default 1000
}

export interface ThermalDerateResult {
  cellTempHotC: number;
  derateFraction: number;      // 0.0 to 1.0
  deratePct: number;           // 0 to 100
  source: 'NOCT_IEC_61215';
}

export function calculateThermalDerate(input: ThermalDerateInput): ThermalDerateResult {
  const G = input.irradianceWm2 ?? 1000;
  const cellTempHotC = input.ambientTempMaxC + (input.module.noctC - 20) * (G / 800);
  const deltaT = Math.max(0, cellTempHotC - 25);
  const deratePct = Math.abs(input.module.tempCoeffPmpPct) * deltaT;
  return {
    cellTempHotC,
    deratePct,
    derateFraction: deratePct / 100,
    source: 'NOCT_IEC_61215',
  };
}

/**
 * Cross-runtime environment flag reader.
 * Works in Node (scripts/tsx, Express) and in the browser (Vite).
 * Never throws. Returns `false` when the flag cannot be read.
 */
export function isRealInternetEnabled(): boolean {
  // Node / server context
  try {
    // @ts-ignore - `process` may not exist in the browser
    if (typeof process !== 'undefined' && process?.env?.REAL_INTERNET === 'true') {
      return true;
    }
  } catch {
    /* ignore */
  }
  // Browser / Vite context
  try {
    // @ts-ignore - `import.meta.env` is Vite-specific and may be undefined
    const meta = import.meta as any;
    if (meta?.env?.VITE_REAL_INTERNET === 'true') {
      return true;
    }
  } catch {
    /* ignore */
  }
  return false;
}

// Single-Axis Tracker with Slope-Aware Backtracking — PR-2a-7
// Faithful TypeScript port of pvlib 0.16.1:
//   - pvlib.tracking.singleaxis (Marion & Dobos, NREL/TP-6A20-58891, Eq. 14-16)
//   - pvlib.shading.projected_solar_zenith_angle (Anderson & Mikofski, NREL/TP-5K00-76626, Eq. 4-5)
//   - pvlib.tracking.calc_surface_orientation / _unit_normal (R = Rz(-az) Rx(-tilt) Ry(theta))
//   - pvlib.irradiance.get_total_irradiance with model='isotropic'
// Pure functions: no I/O, no Date(), no randomness. Float64 throughout.
// Angles are radians internally; degrees only at the API boundary.

export interface TrackerConfig {
  /** GCR = module width / row pitch. Typical 0.30-0.45 for 1P trackers. Must be in (0, 1). */
  gcr: number;
  /** East-west ground slope in degrees (0 = flat). Range [-90, 90]. */
  axisTiltDeg: number;
  /** Maximum mechanical rotation from horizontal (degrees). Typical 45-60. */
  maxRotationDeg: number;
  /** Whether backtracking is enabled. If false, true tracking (row shading possible). */
  enableBacktracking: boolean;
  /** Ground albedo for ground-reflected POA. */
  albedo?: number;
  /** Site latitude (used only for internal default sun path). */
  latitudeDeg?: number;
}

export interface TrackerState {
  /** Rotation angle from horizontal, degrees. pvlib sign convention (axis_azimuth=0). */
  rotationDeg: number;
  /** True tracking angle before backtracking, degrees. */
  trueTrackingDeg: number;
  /** Row-to-row shading fraction (0-1). 0 when backtracking corrects the angle. */
  shadingFraction: number;
  /** POA irradiance on module plane (W/m²). 0 at night. */
  poaWm2: number;
  /** Whether sun is above horizon. */
  isDay: boolean;
  /** Surface tilt/azimuth after rotation (degrees). */
  surfaceTiltDeg: number;
  surfaceAzimuthDeg: number;
  /** Angle of incidence (degrees). */
  aoiDeg: number;
}

export interface SunVector {
  zenithRad: number;
  azimuthRad: number;
}

export interface IrradianceWm2 {
  ghi: number;
  dni: number;
  dhi: number;
}

export interface SunPathPoint extends SunVector, IrradianceWm2 {
  hourOfYear: number;
}

export interface TrackerAnnualResult {
  hourlyStates: TrackerState[];
  /** Annual POA energy (kWh/m²). */
  annualPoaKwhPerM2: number;
  /** Annual row-to-row shading loss fraction (0-1). */
  annualShadingLossFraction: number;
  /** Annual transposition gain over fixed-tilt at optimal angle (%). */
  annualTranspositionGainPct: number;
  /** Share of daytime hours where backtracking modified the angle (%). */
  backtrackingActivationPct: number;
  /** Max absolute rotation reached (degrees). */
  maxAbsRotationDeg: number;
}

const DEG = Math.PI / 180.0;
const RAD = 180.0 / Math.PI;

const sind = (d: number) => Math.sin(d * DEG);
const cosd = (d: number) => Math.cos(d * DEG);
const acosd = (x: number) => Math.acos(Math.max(-1, Math.min(1, x))) * RAD;

/** pvlib.shading.projected_solar_zenith_angle, axis_azimuth = 0 (N-S horizontal axis). */
export function projectedSolarZenithDeg(
  zenithDeg: number,
  azimuthDeg: number,
  axisTiltDeg: number,
  axisAzimuthDeg: number = 0
): number {
  const sx = sind(zenithDeg) * sind(azimuthDeg);
  const sy = sind(zenithDeg) * cosd(azimuthDeg);
  const sz = cosd(zenithDeg);
  const sxPrime = sx * cosd(axisAzimuthDeg) - sy * sind(axisAzimuthDeg);
  const szPrime =
    sx * sind(axisAzimuthDeg) * sind(axisTiltDeg) +
    sy * sind(axisTiltDeg) * cosd(axisAzimuthDeg) +
    sz * cosd(axisTiltDeg);
  return Math.atan2(sxPrime, szPrime) * RAD; // Eq. (5)
}

/** pvlib.tracking._unit_normal + calc_surface_orientation. */
export function surfaceOrientation(
  thetaDeg: number,
  axisTiltDeg: number,
  axisAzimuthDeg: number = 0
): { surfaceTiltDeg: number; surfaceAzimuthDeg: number } {
  const surfaceTiltDeg = acosd(cosd(thetaDeg) * cosd(axisTiltDeg)); // Eq. (1)
  const cA = cosd(-axisAzimuthDeg), sA = sind(-axisAzimuthDeg);
  const cT = cosd(-axisTiltDeg), sT = sind(-axisTiltDeg);
  const cTh = cosd(thetaDeg), sTh = sind(thetaDeg);
  const x = sA * sT * cTh + cA * sTh;
  const y = sA * sTh - cA * sT * cTh;
  let surfaceAzimuthDeg = Math.atan2(x, y) * RAD;
  if (surfaceTiltDeg === 0) surfaceAzimuthDeg = axisAzimuthDeg - 90;
  surfaceAzimuthDeg = ((surfaceAzimuthDeg % 360) + 360) % 360;
  return { surfaceTiltDeg, surfaceAzimuthDeg };
}

/** pvlib.irradiance.aoi_projection (radians math on degrees input). */
export function aoiProjection(
  surfaceTiltDeg: number,
  surfaceAzimuthDeg: number,
  zenithDeg: number,
  azimuthDeg: number
): number {
  return (
    cosd(surfaceTiltDeg) * cosd(zenithDeg) +
    sind(surfaceTiltDeg) * sind(zenithDeg) * cosd(azimuthDeg - surfaceAzimuthDeg)
  );
}

function validateConfig(config: TrackerConfig): void {
  if (!(config.gcr > 0 && config.gcr < 1)) {
    throw new Error(`GCR must be in (0, 1), got ${config.gcr}`);
  }
  if (!(config.axisTiltDeg >= -90 && config.axisTiltDeg <= 90)) {
    throw new Error(`axisTiltDeg must be in [-90, 90], got ${config.axisTiltDeg}`);
  }
  if (!(config.maxRotationDeg > 0 && config.maxRotationDeg <= 90)) {
    throw new Error(`maxRotationDeg must be in (0, 90], got ${config.maxRotationDeg}`);
  }
}

/**
 * pvlib.tracking.singleaxis — single timestep. Pure.
 */
export function computeTrackerState(
  sun: SunVector,
  config: TrackerConfig,
  irr?: IrradianceWm2
): TrackerState {
  validateConfig(config);
  const zenithDeg = sun.zenithRad * RAD;
  const azimuthDeg = ((sun.azimuthRad * RAD) % 360 + 360) % 360;

  if (zenithDeg > 90) {
    return {
      rotationDeg: 0, trueTrackingDeg: 0, shadingFraction: 0, poaWm2: 0,
      isDay: false, surfaceTiltDeg: 0, surfaceAzimuthDeg: 0, aoiDeg: 90,
    };
  }

  // True tracking angle (omega_ideal), axis_azimuth = 0
  const omegaIdeal = projectedSolarZenithDeg(zenithDeg, azimuthDeg, config.axisTiltDeg, 0);

  // Backtracking — Marion & Dobos Eq. 14-16 (pvlib 0.16 form)
  let theta = omegaIdeal;
  let backtracked = false;
  if (config.enableBacktracking) {
    const axesDistance = 1 / config.gcr; // cross_axis_tilt = 0
    const temp = Math.abs(axesDistance * cosd(omegaIdeal));
    if (temp < 1) {
      theta = omegaIdeal - Math.sign(omegaIdeal) * acosd(temp);
      backtracked = true;
    }
  }
  // Mechanical clamp
  const maxA = config.maxRotationDeg;
  theta = Math.max(-maxA, Math.min(maxA, theta));

  // Row-to-row shading fraction: eliminated by backtracking; otherwise the
  // geometry term temp >= 1 means rows shade each other.
  const axesDistance = 1 / config.gcr;
  const temp = Math.abs(axesDistance * cosd(omegaIdeal));
  // PR-2a-7-FOLLOWUP (ISSUE-3): a near-flat panel (|omegaIdeal| < 5 deg, e.g.
  // winter-solstice noon at mid latitudes) casts no row-to-row shadow, so the
  // heuristic temp-1 must not be applied there. With backtracking enabled the
  // correction already guarantees shadingFraction = 0 by design.
  const shadingFraction = (() => {
    // With backtracking enabled, row-to-row shading is eliminated by design.
    if (config.enableBacktracking) return 0.0;
    // PR-2a-7-FOLLOWUP (ISSUE-3): a near-flat panel (|omegaIdeal| < 5 deg, e.g.
    // winter-solstice noon at mid latitudes) casts no row-to-row shadow.
    if (Math.abs(omegaIdeal) < 5.0) return 0.0;
    return Math.min(1, Math.max(0, temp - 1));
  })();

  const { surfaceTiltDeg, surfaceAzimuthDeg } = surfaceOrientation(theta, config.axisTiltDeg, 0);
  const proj = aoiProjection(surfaceTiltDeg, surfaceAzimuthDeg, zenithDeg, azimuthDeg);
  const aoiDeg = acosd(proj);

  // POA — pvlib get_total_irradiance, model='isotropic'
  let poaWm2 = 0;
  if (irr) {
    const albedo = config.albedo ?? 0.2;
    const poaDirect = Math.max(irr.dni * proj, 0); // dni * cos(aoi), floored at 0
    const poaSkyDiffuse = irr.dhi * ((1 + cosd(surfaceTiltDeg)) / 2);
    const poaGroundDiffuse = irr.ghi * albedo * ((1 - cosd(surfaceTiltDeg)) / 2);
    poaWm2 = poaDirect + poaSkyDiffuse + poaGroundDiffuse;
  }

  return {
    rotationDeg: theta,
    trueTrackingDeg: omegaIdeal,
    shadingFraction,
    poaWm2,
    isDay: true,
    surfaceTiltDeg,
    surfaceAzimuthDeg,
    aoiDeg,
  };
}

/**
 * Full-year (or representative-day) simulation. Deterministic.
 * fixedTiltDeg/fixedAzimuthDeg define the fixed-tilt baseline for the
 * transposition-gain metric; pass null to skip the gain computation.
 */
export function simulateTrackerAnnual(
  sunPath: SunPathPoint[],
  config: TrackerConfig,
  fixedBaseline?: { fixedTiltDeg: number; fixedAzimuthDeg: number } | null
): TrackerAnnualResult {
  validateConfig(config);
  const states: TrackerState[] = [];
  let poaSumWh = 0;
  let fixedPoaSumWh = 0;
  let shadeSum = 0;
  let dayHours = 0;
  let backtrackHours = 0;
  let maxAbs = 0;

  for (const p of sunPath) {
    const st = computeTrackerState(
      { zenithRad: p.zenithRad, azimuthRad: p.azimuthRad },
      config,
      { ghi: p.ghi, dni: p.dni, dhi: p.dhi }
    );
    states.push(st);
    if (st.isDay) {
      poaSumWh += st.poaWm2; // 1-hour steps → W·h
      shadeSum += st.shadingFraction;
      dayHours++;
      if (Math.abs(st.rotationDeg - st.trueTrackingDeg) > 1e-9) backtrackHours++;
      maxAbs = Math.max(maxAbs, Math.abs(st.rotationDeg));
      if (fixedBaseline) {
        const proj = aoiProjection(fixedBaseline.fixedTiltDeg, fixedBaseline.fixedAzimuthDeg,
          p.zenithRad * RAD, ((p.azimuthRad * RAD) % 360 + 360) % 360);
        const albedo = config.albedo ?? 0.2;
        const direct = Math.max(p.dni * proj, 0);
        const sky = p.dhi * ((1 + cosd(fixedBaseline.fixedTiltDeg)) / 2);
        const ground = p.ghi * albedo * ((1 - cosd(fixedBaseline.fixedTiltDeg)) / 2);
        fixedPoaSumWh += direct + sky + ground;
      }
    }
  }

  const annualPoaKwhPerM2 = poaSumWh / 1000;
  const annualShadingLossFraction = dayHours > 0 ? shadeSum / dayHours : 0;
  const annualTranspositionGainPct =
    fixedBaseline && fixedPoaSumWh > 0
      ? ((poaSumWh - fixedPoaSumWh) / fixedPoaSumWh) * 100
      : 0;

  return {
    hourlyStates: states,
    annualPoaKwhPerM2,
    annualShadingLossFraction,
    annualTranspositionGainPct,
    backtrackingActivationPct: dayHours > 0 ? (backtrackHours / dayHours) * 100 : 0,
    maxAbsRotationDeg: maxAbs,
  };
}

